const app=document.getElementById('app');
const LEVELS=[['개념 이해','설명과 사진 속 단서 찾기'],['연결과 비교','설명과 이름의 관계 살피기'],['상황 판단','생활 속 상황에 개념 적용하기']];
let selectedLevel=1,exam=[],answers={},position=0,phase='home',result=null,filter='all',attempt=0;
let selectedChapter='three';
const CHAPTERS={three:{name:'삼국시대',subtitle:'경쟁하고 교류하며 발전한 고대 국가',scope:'32~49',topics:TOPICS,create:createMixedExam},goryeo:{name:'고려',subtitle:'다양성을 품은 고려',scope:'52~67',topics:GORYEO.topics,create:GORYEO.createMixedExam}};
const chapter=()=>CHAPTERS[selectedChapter];
const previous={};
function selectChapter(key){if(!CHAPTERS[key]||phase!=='home')return;selectedChapter=key;exam=[];answers={};result=null;renderHome();app.querySelector(`[data-chapter="${key}"]`)?.focus({preventScroll:true});}
function chapterTabs(){return `<nav class="chapter-tabs" role="tablist" aria-label="공부할 단원 선택">${Object.entries(CHAPTERS).map(([key,c])=>`<button type="button" id="tab-${key}" role="tab" data-chapter="${key}" aria-selected="${key===selectedChapter}" aria-controls="chapter-content" tabindex="${key===selectedChapter?0:-1}">${c.name}<small>${key==='three'?'삼국 · 가야 · 통일신라 · 발해':'고려의 건국 · 교류 · 생활 · 문화'}</small></button>`).join('')}</nav>`;}
function updateChapterLabels(){document.querySelector('.scope').textContent=`${chapter().name} · 교과서 ${chapter().scope}쪽`;document.querySelector('footer').textContent=`사진 속 교과서 「${chapter().subtitle}」를 바탕으로 만든 연습 문제예요.`;}

const escapeHTML=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escapeHTML;
function renderHome(){phase='home';updateChapterLabels();app.innerHTML=`${chapterTabs()}<div id="chapter-content" role="tabpanel" aria-labelledby="tab-${selectedChapter}"><section class="intro"><div><span class="eyebrow">${chapter().subtitle}</span><h1>오늘은 어떤 단계에 도전할까요?</h1><p class="sub">천천히 풀어도 괜찮아요. 제출한 뒤 해설로 다시 배워요.</p></div><div class="stamp"><strong>30문제</strong>정답 수를 100점으로 환산</div></section><section class="panel" aria-label="시험 난이도 선택"><div class="section-top"><h2>나에게 맞는 난이도</h2><span class="muted">1단계부터 차근차근 도전해 보세요.</span></div><div class="levels">${LEVELS.map(([name,desc],i)=>`<button class="level" data-level="${i+1}" aria-pressed="${selectedLevel===i+1}"><span class="num">${i+1}단계</span><strong>${name}</strong><small>${desc}</small></button>`).join('')}</div><div class="chips">${chapter().topics.map((t,i)=>`<span class="chip">${t} · ${[8,8,7,7][i]}문제</span>`).join('')}</div><div class="begin-row"><div><strong id="level-summary">${selectedLevel}단계 · ${LEVELS[selectedLevel-1][0]}</strong><p class="muted">30문제 · 빈칸 단답형과 사진 이름 쓰기 포함 · 제출 후 채점과 해설</p></div><button class="primary" id="start">새 시험 시작하기</button></div></section><div class="notes"><span>문제는 한 번에 하나씩 보여요. 번호를 누르면 언제든 돌아갈 수 있어요.</span><span>객관식 14문제 · 빈칸 단답형 12문제 · 사진 이름 쓰기 4문제를 새 조합으로 출제해요. 여러 번 풀면 일부 내용은 다시 나올 수 있어요.</span></div></div>`;
app.querySelectorAll('[data-chapter]').forEach(b=>{b.onclick=()=>selectChapter(b.dataset.chapter);b.onkeydown=ev=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(ev.key)){ev.preventDefault();selectChapter(ev.key==='Home'?'three':ev.key==='End'?'goryeo':selectedChapter==='three'?'goryeo':'three');}};});
app.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{selectedLevel=Number(b.dataset.level);app.querySelectorAll('[data-level]').forEach(x=>x.setAttribute('aria-pressed',x===b?'true':'false'));document.getElementById('level-summary').textContent=`${selectedLevel}단계 · ${LEVELS[selectedLevel-1][0]}`;});
document.getElementById('start').onclick=()=>startExam(selectedLevel);
}
function startExam(level){if(!Number.isInteger(level)||level<1||level>3)throw Error('1~3단계를 선택해 주세요.');selectedLevel=level;const historyKey=`${selectedChapter}-${level}`;exam=chapter().create(level+1,previous[historyKey]||[]);previous[historyKey]=exam.map(q=>q.id);answers={};position=0;result=null;attempt++;phase='exam';renderExam();focusQuestion();return {attempt,chapter:selectedChapter,level,count:exam.length};}
function focusQuestion(){document.getElementById('question-title')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}

function answeredCount(){return exam.filter(q=>isAnswered(q,answers)).length;}
function questionControls(q){
 if(q.cloze){const [before,after]=q.cloze.split('{{blank}}');return `<div class="cloze-answer"><p class="cloze-sentence">${e(before)}<input class="inline-blank" id="written-answer" type="text" maxlength="120" autocomplete="off" spellcheck="false" aria-label="빈칸 답안" aria-describedby="written-help" value="${e(answers[q.id]??'')}" placeholder="빈칸에 입력">${e(after)}</p><p class="muted" id="written-help">빈칸에 알맞은 낱말을 적어 주세요. 띄어쓰기는 달라도 괜찮아요.</p></div>`;}
 const photo=q.image?`<figure class="question-photo"><img src="${e(q.image)}" alt="교과서에서 가져온 문제 사진"><figcaption>사진을 자세히 살펴보세요. 교과서 속 유물·유적 또는 생활 모습이에요.</figcaption></figure>`:'';
 if(q.type==='short')return `${photo}<div class="short-answer"><label for="written-answer">답을 직접 써 보세요.</label><input id="written-answer" type="text" maxlength="120" autocomplete="off" spellcheck="false" value="${e(answers[q.id]??'')}" placeholder="${q.exactName?'사진 속 정확한 이름을 입력하세요':'이름이나 핵심 낱말을 입력하세요'}" aria-describedby="written-help"><p id="written-help" class="muted">${q.exactName?'띄어쓰기는 달라도 괜찮아요. 고려청자는 종류나 기법만 쓰지 말고 교과서의 전체 이름을 적어 주세요.':'띄어쓰기는 달라도 괜찮아요. 이름이나 낱말로 짧게 답해 주세요.'}</p></div>`;
 return `${photo}<div class="answers" role="radiogroup" aria-labelledby="question-title">${q.options.map((o,i)=>`<button type="button" class="choice" role="radio" aria-checked="${answers[q.id]===o}" data-option="${i}"><span class="circle" aria-hidden="true">${i+1}</span><span>${e(o)}</span></button>`).join('')}</div>`;
}
function updateProgress(index){let done=answeredCount();document.getElementById('done-text').textContent=`${done} / ${exam.length} 완료`;app.querySelector('.progress').setAttribute('aria-valuenow',done);app.querySelector('.progress-fill').style.width=`${done/exam.length*100}%`;let n=app.querySelector(`[data-position="${index}"]`);let filled=isAnswered(exam[index],answers);n?.classList.toggle('done',filled);n?.setAttribute('aria-label',`${index+1}번 문제, ${filled?'답함':'미응답'}`);return {answered:done,total:exam.length};}
function writeAnswer(index,text){if(phase!=='exam'||!Number.isInteger(index)||index<0||index>=exam.length||exam[index].type!=='short'||typeof text!=='string'||text.length>120)throw Error('주관식 답은 120자 이내로 적어 주세요.');if(text.trim())answers[exam[index].id]=text;else delete answers[exam[index].id];if(index===position){let input=document.getElementById('written-answer');if(input&&input.value!==text)input.value=text;}return updateProgress(index);}

function renderExam(){let q=exam[position],done=answeredCount();app.innerHTML=`<div class="exam-head"><div><span class="eyebrow">${chapter().name} · ${attempt}번째 도전 · ${selectedLevel}단계 ${LEVELS[selectedLevel-1][0]}</span><h1>${chapter().name} 탐험 시험</h1></div><span class="tag">30문제 · 100점 만점</span></div><div class="layout"><section class="panel"><div class="question-top"><span class="qno">문제 ${position+1} / ${exam.length}</span><span class="tag">${e(chapter().topics[q.topic])} · ${q.photo?'사진 문제':q.cloze?'빈칸 단답형':q.type==='short'?'주관식':'객관식'}</span></div><h2 class="question" id="question-title" tabindex="-1">${e(q.q)}</h2>${questionControls(q)}<div class="qnav"><button class="secondary" id="prev" ${position===0?'disabled':''}>이전 문제</button>${position<exam.length-1?'<button class="primary" id="next">다음 문제</button>':'<button class="primary" id="last-submit">답안 제출하기</button>'}</div></section><aside class="panel sidebar" aria-label="문제 이동과 제출"><div class="side-title"><strong>풀이 현황</strong><span id="done-text" class="muted" aria-live="polite">${done} / ${exam.length} 완료</span></div><div class="progress" role="progressbar" aria-label="답한 문제 수" aria-valuenow="${done}" aria-valuemin="0" aria-valuemax="${exam.length}"><div class="progress-fill" style="width:${done/exam.length*100}%"></div></div><div class="numbers">${exam.map((item,i)=>`<button class="number ${isAnswered(item,answers)?'done':''} ${i===position?'current':''}" data-position="${i}" aria-label="${i+1}번 문제, ${isAnswered(item,answers)?'답함':'미응답'}" ${i===position?'aria-current="step"':''}>${i+1}</button>`).join('')}</div><p class="side-help">파란 번호는 답한 문제예요.<br>번호를 눌러 답을 바꿀 수 있어요.</p><button class="primary side-submit" id="submit">답안 제출하기</button></aside></div>`;
app.querySelectorAll('[data-option]').forEach(b=>{b.onclick=()=>chooseAnswer(position,Number(b.dataset.option));b.onkeydown=ev=>{let delta=ev.key==='ArrowDown'||ev.key==='ArrowRight'?1:ev.key==='ArrowUp'||ev.key==='ArrowLeft'?-1:0;if(delta){ev.preventDefault();let i=(Number(b.dataset.option)+delta+q.options.length)%q.options.length;chooseAnswer(position,i);app.querySelector(`[data-option="${i}"]`).focus();}};});
if(q.type==='short')document.getElementById('written-answer').oninput=ev=>writeAnswer(position,ev.target.value);
app.querySelectorAll('[data-position]').forEach(b=>b.onclick=()=>{position=Number(b.dataset.position);renderExam();focusQuestion();});
document.getElementById('prev').onclick=()=>{position--;renderExam();focusQuestion();};
if(position<exam.length-1)document.getElementById('next').onclick=()=>{position++;renderExam();focusQuestion();};else document.getElementById('last-submit').onclick=requestSubmit;
document.getElementById('submit').onclick=requestSubmit;
}
function chooseAnswer(index,option){if(phase!=='exam'||!Number.isInteger(index)||index<0||index>=exam.length||exam[index].type==='short'||!Number.isInteger(option)||option<0||option>=exam[index].options.length)throw Error('문제 번호와 보기 번호를 확인해 주세요.');answers[exam[index].id]=exam[index].options[option];if(index===position){app.querySelectorAll('[data-option]').forEach(b=>b.setAttribute('aria-checked',Number(b.dataset.option)===option?'true':'false'));}return updateProgress(index);}
function requestSubmit(){let missing=exam.filter(q=>!isAnswered(q,answers)).length;if(!missing){submitExam();return;}let dialog=document.createElement('dialog');dialog.innerHTML=`<h2>아직 ${missing}문제를 풀지 않았어요.</h2><p>답하지 않은 문제는 0점으로 채점돼요.<br>계속 풀거나 지금 제출할 수 있어요.</p><div class="dialog-actions"><button class="secondary" id="keep-solving">계속 풀기</button><button class="primary" id="submit-anyway">지금 제출하기</button></div>`;document.body.append(dialog);dialog.showModal();dialog.querySelector('#keep-solving').onclick=()=>{dialog.close();dialog.remove();position=exam.findIndex(q=>!isAnswered(q,answers));renderExam();focusQuestion();};dialog.querySelector('#submit-anyway').onclick=()=>{dialog.close();dialog.remove();submitExam();};dialog.oncancel=()=>dialog.remove();}
function submitExam(){if(phase!=='exam')throw Error('진행 중인 시험이 없어요.');result=gradeExam(exam,answers,chapter().topics);phase='result';filter='all';renderResult();window.scrollTo({top:0,behavior:'instant'});document.getElementById('result-title').focus({preventScroll:true});return {score:result.score,correct:result.correct,total:exam.length,topics:result.topics};}
function renderResult(){let message=result.score===100?'모든 문제를 맞혔어요! 배운 내용을 잘 이해했네요.':result.score>=80?'잘 풀었어요! 헷갈린 내용만 해설로 다시 살펴봐요.':result.score>=50?'차근차근 배우고 있어요. 해설을 읽고 다시 도전해 봐요.':'괜찮아요. 해설을 읽으며 한 가지씩 알아가면 돼요.';app.innerHTML=`<div class="intro"><div><span class="eyebrow">${chapter().name} · ${attempt}번째 도전 · ${selectedLevel}단계 ${LEVELS[selectedLevel-1][0]}</span><h1 id="result-title" tabindex="-1">답안 채점이 끝났어요!</h1><p class="sub">${message}</p></div></div><section class="summary" aria-label="채점 결과"><div class="score"><strong>${result.score}</strong>점<small>${exam.length}문제 중 ${result.correct}문제 정답</small></div><div class="topic-scores">${result.topics.map(t=>`<div class="topic-score">${t.name}<strong>${t.correct} / ${t.total}</strong><div class="progress"><div class="progress-fill" style="width:${t.correct/t.total*100}%"></div></div></div>`).join('')}</div></section><div class="result-actions"><button class="primary" id="retry">같은 단계로 새 시험</button><button class="secondary" id="change-level">단원·난이도 다시 고르기</button></div><section aria-label="문제별 풀이 해설"><div class="section-top"><h2>정답과 풀이 해설</h2><span class="muted">정답 수를 100점으로 환산 · 미응답은 오답</span></div><div class="review-controls"><button class="filter ${filter==='all'?'active':''}" data-filter="all" aria-pressed="${filter==='all'}">전체 ${exam.length}문제</button><button class="filter ${filter==='wrong'?'active':''}" data-filter="wrong" aria-pressed="${filter==='wrong'}">틀린 문제 ${exam.length-result.correct}개</button></div><div class="reviews">${result.items.map((q,i)=>({q,i})).filter(({q})=>filter!=='wrong'||!q.correct).map(({q,i})=>`<article class="panel review"><div class="question-top"><span class="qno">${i+1}번 · ${e(chapter().topics[q.topic])}</span><span class="status ${q.correct?'':'wrong'}">${q.correct?'정답':q.chosen===null?'미응답 · 0점':'다시 살펴봐요 · 0점'}</span></div><h3>${e(q.q)}</h3>${q.cloze?`<p class="cloze-review">${e(q.cloze.replace('{{blank}}','[ '+q.a+' ]'))}</p>`:''}${q.image?`<img class="review-photo" src="${e(q.image)}" alt="교과서 속 ${e(q.a)} 사진" loading="lazy">`:''}<div class="review-answer">내 답: ${q.chosen===null?'답하지 않았어요.':e(q.chosen)}</div><div class="review-answer correct-answer"><strong>정답:</strong> ${e(q.a)}</div><p class="explanation"><strong>풀이 해설</strong><br>${e(q.why)}${q.type==='short'?(q.exactName?'\n띄어쓰기는 무시하며, 교과서에 나온 구체적인 이름으로 채점해요.':'\n띄어쓰기 차이와 미리 정한 같은 뜻의 이름은 정답으로 인정해요.'):''}</p><span class="page">교과서 ${e(q.page)}쪽</span></article>`).join('')||'<div class="panel empty">틀린 문제가 없어요. 모두 잘 풀었어요!</div>'}</div></section>`;
document.getElementById('retry').onclick=()=>startExam(selectedLevel);document.getElementById('change-level').onclick=()=>{renderHome();window.scrollTo({top:0,behavior:'instant'});};app.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;renderResult();app.querySelector(`[data-filter="${filter}"]`).focus({preventScroll:true});});}
renderHome();
const modelContext=document.modelContext;
if(modelContext?.registerTool){const lifecycle=new AbortController();const register=t=>{try{Promise.resolve(modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
register({name:'start_history_exam',title:'새 사회 시험 시작',description:'선택한 1~3단계에서 30문제를 새로 뽑고 현재 시험을 새 시험으로 바꿉니다.',inputSchema:{type:'object',properties:{level:{type:'integer',minimum:1,maximum:3},chapter:{type:'string',enum:['three','goryeo']}},required:['level'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({level,chapter:key})=>{if(key){if(!CHAPTERS[key])throw Error('단원을 확인해 주세요.');selectedChapter=key;updateChapterLabels();}return startExam(level);}});
register({name:'read_history_exam',title:'사회 시험 상태 읽기',description:'현재 난이도, 문제와 보기, 답한 문제 수를 읽습니다. 제출 전 정답은 반환하지 않습니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({phase,chapter:selectedChapter,level:selectedLevel,answered:answeredCount(),questions:exam.map((q,i)=>({number:i+1,question:q.cloze?q.cloze.replace('{{blank}}','[빈칸]'):q.q,type:q.type,photo:q.photo??false,image:q.image??null,options:q.options,chosen:answers[q.id]??null})),result:phase==='result'?{score:result.score,correct:result.correct}:null})});
register({name:'answer_history_questions',title:'사회 시험 답 고르거나 쓰기',description:'여러 문제에 답합니다. 객관식에는 보기 번호 option, 주관식에는 직접 쓴 답 text를 보냅니다. 번호는 1부터 시작하며 채점하지 않습니다.',inputSchema:{type:'object',properties:{answers:{type:'array',items:{type:'object',properties:{number:{type:'integer',minimum:1,maximum:30},option:{type:'integer',minimum:1,maximum:4},text:{type:'string',maxLength:120}},required:['number'],additionalProperties:false}}},required:['answers'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(phase!=='exam'||!Array.isArray(input.answers)||!input.answers.every(a=>{if(!Number.isInteger(a.number)||a.number<1||a.number>exam.length)return false;let q=exam[a.number-1];return q.type==='short'?typeof a.text==='string'&&a.text.length<=120&&a.option===undefined:Number.isInteger(a.option)&&a.option>=1&&a.option<=q.options.length&&a.text===undefined;}))throw Error('객관식은 보기 번호, 주관식은 글로 답해 주세요.');input.answers.forEach(a=>{if(exam[a.number-1].type==='short')writeAnswer(a.number-1,a.text);else chooseAnswer(a.number-1,a.option-1);});return {answered:answeredCount(),total:exam.length};}});
register({name:'submit_history_exam',title:'사회 시험 답안 제출',description:'모든 문제에 답한 시험을 제출해 채점하고 정답과 해설을 화면에 표시합니다. 미응답 문제가 있으면 제출하지 않습니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:()=>{if(phase!=='exam'||exam.some(q=>!isAnswered(q,answers)))throw Error('모든 문제를 푼 다음 제출해 주세요.');return submitExam();}});
window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
